def get_owned_invoice(db, invoice_id, user):
    inv = db.get(Invoice, invoice_id)
    if inv is None or inv.owner_id != user.id:
        raise HTTPException(status_code=404)
    return inv

@app.get("/invoices/{invoice_id}")
def read_invoice(invoice_id: int, user=Depends(current_user), db=Depends(get_db)):
    return get_owned_invoice(db, invoice_id, user)

